buggy.described_examples:
import pandas as pd
import numpy as np

# Test 1: dtype = pd.SparseDtype(values.dtype, fill) with various types and fill values
test_types = ['M8[s]', 'm8[s]', 'M8[ns]', 'm8[ns]']
fill_values = [pd.NaT, np.nan, np.float64('nan'), pd.NA]

for dtype_str in test_types:
    values = np.array([1], 'i8').astype(dtype_str)
    values[0] = 'NaT'

    for fill in fill_values:
        try:
            dtype = pd.SparseDtype(values.dtype, fill)
            probe(f"test_na_fill_value_normalized {dtype_str} {type(fill).__name__}", dtype)
        except Exception as e:
            probe_exception(f"test_na_fill_value_normalized {dtype_str} {type(fill).__name__}", e)

# Test 2: values = np.array([1,2,3], 'i8').astype(...) with SparseArray
kinds_units = [
    ('M8', 's'),
    ('M8', 'ns'),
    ('m8', 's'),
    ('m8', 'ns'),
]

for kind, unit in kinds_units:
    values = np.array([1, 2, 3], 'i8').astype(f'{kind}[{unit}]')
    values[1] = 'NaT'

    for fill in fill_values:
        try:
            arr = pd.arrays.SparseArray(values, fill_value=fill)
            probe(f"test_datetimelike_na_fill_value_normalized {kind}[{unit}] {type(fill).__name__}", arr)
        except Exception as e:
            probe_exception(f"test_datetimelike_na_fill_value_normalized {kind}[{unit}] {type(fill).__name__}", e)

